[Part] ReplicatedStorage.Assets.Effects.UniqueSwingFX.Unique_Moonrend.BladeTrailRig
  @NormalizedBladeBase = Vector3.new(0.211, 0.282, 0.000)
  @WeaponKey = "Unique_Moonrend"
  @ProfileCoordinates = "Handle local coordinates: X*Handle.Size.X, Y*Handle.Size.Y; pivot is Handle.CFrame"
  @TextureFallback = "Native untextured Trails; existing uploaded masks failed current-place PreloadAsync. Small particle accents use preloaded Roblox bundled textures."
